  /** STRING_LIST_RET_STRING: opcode 229 `PhysicsDirectSpaceState3D.intersect_ray` (IMMEDIATE_RESULT). PhysicsDirectSpaceState3D.intersect_ray (receiver: a node of the world; from, to, mask and flags as text parts) packs the collider and the hit; the generic tier queries the same ray with a PhysicsRayQueryParameters3D. */
  private fun rowStringListRetString() = row("STRING_LIST_RET_STRING", "PhysicsDirectSpaceState3D.intersect_ray") {
    val query = freshRef("PhysicsRayQueryParameters3D")
    oracle(query, "set_from", Vector3(4.0, 3.0, 4.0))
    oracle(query, "set_to", Vector3(4.0, -3.0, 4.0))
    val r = freshChild("Node3D")
    val result = GodotBackendCalls.invokeStringListRetString(D.PHYSICSDIRECTSPACESTATE3D_INTERSECT_RAY, r.requireOpenHandle(), listOf("4.0", "3.0", "4.0", "4.0", "-3.0", "4.0", "4294967295", "1"))
    val world = oracle(r, "get_world_3d") as GodotObject
    val hit = oracle(oracle(world, "get_direct_space_state") as GodotObject, "intersect_ray", query) as Map<*, *>
    val entries = track(WebPackedValues.decodeVariant(result.substringAfter('\u001F'))) as Map<*, *>
    val collider = objOf(result.substringBefore('\u001F'))
    check(near(entries["position"], hit["position"]) && near(entries["normal"], hit["normal"]) && near(collider, hit["collider"]), "the hit the generic intersect_ray reports", result)
  }

